function sql(value) { if (value === undefined || value === null || String(value).trim() === '') return 'NULL'; return "'" + String(value).replace(/'/g, "''") + "'"; }
const body = $json.body || $json;
const publicationJobId = String(body.publicationJobId || body.publication_job_id || '').trim();
const generationJobId = String(body.generationJobId || body.generation_job_id || '').trim();
const outputUrl = String(body.outputUrl || body.output_url || '').trim();
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (!uuidRegex.test(publicationJobId) || !uuidRegex.test(generationJobId) || !outputUrl) {
  return [{ json: { ok: false, skip: true, error: 'publicationJobId, generationJobId and outputUrl are required' } }];
}
const query = "SELECT pj.publication_job_id AS \"publicationJobId\", pj.avatar, pj.scene, pj.asset_type AS \"assetType\", pj.format, pj.prompt_pack AS \"jobPromptPack\", pj.metadata AS \"publicationMetadata\", gj.job_id AS \"generationJobId\", gj.prompt_pack AS \"promptPack\", gj.run_mode AS \"runMode\", ac.avatar_short AS \"avatarShort\", " + sql(outputUrl) + " AS \"outputUrl\" FROM publication_jobs pj JOIN generation_jobs gj ON gj.job_id = " + sql(generationJobId) + "::uuid LEFT JOIN avatar_catalog ac ON ac.avatar = pj.avatar WHERE pj.publication_job_id = " + sql(publicationJobId) + "::uuid LIMIT 1;";
return [{ json: { ok: true, skip: false, query, outputUrl } }];

const fs = require('fs');
const path = require('path');
const row = $input.first()?.json || {};
if (!row.publicationJobId || !row.generationJobId) return [{ json: { ok: false, error: 'Publication/generation context not found' } }];
const gateway = await this.helpers.httpRequest({ method: 'POST', url: 'http://ai-gateway:8095/comfy/download-output', headers: { 'Content-Type': 'application/json', 'X-Request-Id': 'publication-ingest-' + row.publicationJobId }, body: { outputUrl: row.outputUrl }, json: true, timeout: 120000 });
if (!gateway?.ok || !gateway.base64) return [{ json: { ok: false, error: gateway?.error || 'Comfy output download failed', gateway } }];
const safeJob = String(row.publicationJobId).replace(/[^a-zA-Z0-9_-]/g, '-');
const inputDir = '/home/node/.n8n-files/inbox/publication-' + safeJob + '-' + Date.now();
fs.mkdirSync(inputDir, { recursive: true });
const ext = gateway.mimeType === 'image/jpeg' ? 'jpg' : 'png';
const fileName = 'estefania-comfy-publication-' + safeJob + '.' + ext;
const filePath = path.join(inputDir, fileName);
fs.writeFileSync(filePath, Buffer.from(gateway.base64, 'base64'));
return [{ json: { ok: true, publicationJobId: row.publicationJobId, generationJobId: row.generationJobId, avatar: row.avatar, avatarShort: row.avatarShort || 'estefania', scene: row.scene, assetType: row.assetType || 'raw-image', workflow: 'comfy-cloud-api-estefania-v1', model: 'flux1-dev-fp8 + uso-flux1', seed: 0, version: 1, inputDir, outputUrl: row.outputUrl, comfyFilename: gateway.filename, comfySubfolder: gateway.subfolder, mimeType: gateway.mimeType, byteLength: gateway.byteLength, sha256: gateway.sha256, downloadedFile: filePath, downloadedFileName: fileName, promptPack: row.promptPack || row.jobPromptPack || {}, publicationMetadata: row.publicationMetadata || {} } }];

const context = $('Download Comfy Output To Inbox').first().json;
const rows = $input.all().map(item => item.json || {});
const registered = rows.find(item => item.assetId || item.asset_id || item.sha256 === context.sha256) || rows[0] || {};
const returnedAssetId = registered.assetId || registered.asset_id || null;
function sql(value) { if (value === undefined || value === null || String(value).trim() === '') return 'NULL'; return "'" + String(value).replace(/'/g, "''") + "'"; }
function sqlJson(value) { return sql(JSON.stringify(value || {})) + '::jsonb'; }
const promptPack = context.promptPack && typeof context.promptPack === 'object' ? context.promptPack : {};
const compositionPolicy = promptPack.compositionPolicy && typeof promptPack.compositionPolicy === 'object' ? promptPack.compositionPolicy : {};
const rejectIf = Array.isArray(compositionPolicy.rejectIf) ? compositionPolicy.rejectIf.map(String) : [];
const qaFlags = [];
if (rejectIf.some((item) => item.toLowerCase().includes('foot') || item.toLowerCase().includes('toe'))) qaFlags.push('foot-risk-review');
if (rejectIf.some((item) => item.toLowerCase().includes('hand') || item.toLowerCase().includes('finger'))) qaFlags.push('hand-risk-review');
if (rejectIf.some((item) => item.toLowerCase().includes('identity') || item.toLowerCase().includes('face'))) qaFlags.push('identity-review');
const qa = {
  contractVersion: 'publication-image-qa-v1',
  provider: 'heuristic-pre-visual',
  status: qaFlags.length ? 'review_required' : 'pass',
  scores: { identity: 0.5, hands: qaFlags.includes('hand-risk-review') ? 0.4 : 0.7, feet: qaFlags.includes('foot-risk-review') ? 0.4 : 0.7, composition: 0.6, publishability: 0.5 },
  flags: qaFlags,
  notes: ['Heuristic QA only; human review is still required before publication.', 'Use visual QA provider in US-030 for pixel-level identity/anatomy scoring.'],
  correctionRecommended: qaFlags.includes('hand-risk-review') || qaFlags.includes('foot-risk-review'),
  correctionMode: qaFlags.includes('hand-risk-review') || qaFlags.includes('foot-risk-review') ? 'manual-or-future-inpaint-pass' : null,
  reviewedAt: new Date().toISOString()
};
const metadata = {
  source: 'publication-comfy-output-ingest',
  publicationJobId: context.publicationJobId,
  generationJobId: context.generationJobId,
  outputUrl: context.outputUrl,
  comfyFilename: context.comfyFilename,
  comfySubfolder: context.comfySubfolder,
  downloadedFileName: context.downloadedFileName,
  sha256: context.sha256,
  qa
};
const assetPredicate = returnedAssetId
  ? '(asset_id = ' + sql(returnedAssetId) + ' OR sha256 = ' + sql(context.sha256) + ')'
  : 'sha256 = ' + sql(context.sha256);
const query = "WITH asset_target AS (SELECT * FROM canonical_asset_registry WHERE " + assetPredicate + " ORDER BY created_at DESC LIMIT 1), asset_update AS (UPDATE canonical_asset_registry car SET metadata = COALESCE(car.metadata, '{}'::jsonb) || (" + sqlJson(metadata) + " || jsonb_build_object('bucket', car.bucket, 'objectPath', car.object_path, 'assetId', car.asset_id)), review_notes = COALESCE(car.review_notes, 'Generated by Comfy Cloud API for publication job') FROM asset_target t WHERE car.asset_id = t.asset_id RETURNING car.*), generated AS (INSERT INTO generated_assets (generated_asset_id, job_id, asset_id, avatar, scene, asset_type, status, review_notes, metadata, created_at, updated_at) SELECT gen_random_uuid(), " + sql(context.generationJobId) + "::uuid, asset_id::uuid, avatar, scene, asset_type, 'generated', 'Generated by Comfy Cloud API for publication job', (" + sqlJson(metadata) + " || jsonb_build_object('bucket', bucket, 'objectPath', object_path, 'assetId', asset_id)), now(), now() FROM asset_update ON CONFLICT (asset_id) DO UPDATE SET job_id = EXCLUDED.job_id, status = 'generated', metadata = generated_assets.metadata || EXCLUDED.metadata, updated_at = now() RETURNING *), generation_update AS (UPDATE generation_jobs SET status = 'review_required', result_payload = result_payload || (" + sqlJson(metadata) + " || jsonb_build_object('assetId', (SELECT asset_id FROM asset_update LIMIT 1), 'bucket', (SELECT bucket FROM asset_update LIMIT 1), 'objectPath', (SELECT object_path FROM asset_update LIMIT 1))), completed_at = now(), updated_at = now() WHERE job_id = " + sql(context.generationJobId) + "::uuid RETURNING *), publication_update AS (UPDATE publication_jobs SET status = 'review-ready', metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('latestGeneratedAssetId', (SELECT asset_id FROM asset_update LIMIT 1), 'latestGeneratedAssetObjectPath', (SELECT object_path FROM asset_update LIMIT 1), 'latestGeneratedAssetSha256', (SELECT sha256 FROM asset_update LIMIT 1), 'latestGeneratedAssetQa', " + sqlJson(qa) + ", 'generatedAssetReadyAt', now()), updated_at = now() WHERE publication_job_id = " + sql(context.publicationJobId) + "::uuid RETURNING *) SELECT (SELECT row_to_json(asset_update) FROM asset_update LIMIT 1) AS asset, (SELECT row_to_json(generated) FROM generated LIMIT 1) AS generated_asset, (SELECT row_to_json(generation_update) FROM generation_update LIMIT 1) AS generation_job, (SELECT row_to_json(publication_update) FROM publication_update LIMIT 1) AS publication_job;";
return [{ json: { ok: true, query, returnedAssetId, context } }];

function parse(v) { if (!v) return null; if (typeof v === 'string') { try { return JSON.parse(v); } catch { return null; } } return v; }
const row = $input.first()?.json || {};
const asset = parse(row.asset); const generatedAsset = parse(row.generated_asset); const generationJob = parse(row.generation_job); const publicationJob = parse(row.publication_job);
if (!asset?.asset_id) return [{ json: { ok: false, error: 'Asset ingest link failed', row } }];
return [{ json: { ok: true, ingested: true, assetId: asset.asset_id, generatedAssetId: generatedAsset?.generated_asset_id || null, generationJobId: generationJob?.job_id || null, publicationJobId: publicationJob?.publication_job_id || null, publicationStatus: publicationJob?.status || null, generationStatus: generationJob?.status || null, objectPath: asset.object_path, bucket: asset.bucket } }];
